INSERT INTO roles (id, name, display_name, description, is_system) VALUES
  (1, 'super_admin', 'Super Admin', 'Supreme authority with complete system governance and security administration', 1),
  (2, 'admin', 'Admin', 'Full store operations, staff management, catalog, and reporting', 1),
  (3, 'inventory_manager', 'Inventory Manager', 'Product catalog, stock adjustments, purchase orders, and supplier management', 1),
  (4, 'cashier', 'Cashier', 'Point of Sale checkout register, customer loyalty CRM, and cash drawer transactions', 1);
INSERT INTO permissions (id, name, display_name, description, group_name) VALUES
  (1, 'manage_users', 'Manage Staff', 'Create and update staff member profiles', 'Staff'),
  (2, 'delete_staff', 'Delete Staff', 'Deactivate and delete employee accounts', 'Staff'),
  (3, 'admin_reset_password', 'Reset Employee Passwords', 'Perform direct administrative password resets for staff members', 'Staff'),
  (4, 'manage_roles', 'Manage Roles & RBAC', 'Configure dynamic roles and permission matrices', 'Staff'),
  (5, 'manage_shifts', 'Manage Work Shifts', 'Configure and assign operational shift schedules', 'Staff'),
  (6, 'manage_tasks', 'Assign Staff Tasks', 'Create and assign operational duties to team members', 'Team'),
  (7, 'manage_products', 'Manage Products', 'Add and edit inventory catalog products and pricing', 'Inventory'),
  (8, 'delete_products', 'Delete Products', 'Remove catalog items permanently from inventory', 'Inventory'),
  (9, 'adjust_stock', 'Adjust Stock Counts', 'Modify inventory on-hand counts, reconciliations and write-offs', 'Inventory'),
  (10, 'manage_categories', 'Manage Categories', 'Create, update, and remove product merchandise categories', 'Inventory'),
  (11, 'print_barcodes', 'Print Barcodes', 'Generate and print SKU barcode label stickers', 'Inventory'),
  (12, 'view_cost_prices', 'View Cost & Profit Margins', 'Inspect wholesale supplier unit costs and item profit margins', 'Inventory'),
  (13, 'process_sale', 'Process POS Sales', 'Operate checkout POS register, scan items, and finalize transactions', 'Sales'),
  (14, 'apply_discounts', 'Apply Custom Discounts', 'Authorize manual cart discount percentages at checkout', 'Sales'),
  (15, 'hold_orders', 'Park & Hold Orders', 'Hold active shopping carts and resume parked tickets', 'Sales'),
  (16, 'manage_currency', 'Change Exchange Rate', 'Modify USD ($) to KHR (៛) exchange conversion rates', 'Sales'),
  (17, 'adjust_drawer_cash', 'Adjust Drawer Cash', 'Open drawer, count floats, and reconcile shift end balances', 'Sales'),
  (18, 'view_reports', 'View Analytics & Reports', 'Access financial executive summaries and sales reporting views', 'Reports'),
  (19, 'export_reports', 'Export CSV/Excel Reports', 'Download analytical audit spreadsheets and sales data', 'Reports'),
  (20, 'view_profit_loss', 'View Profit & Loss Margins', 'View net income profit margins, revenue vs. cost breakdown', 'Reports'),
  (21, 'manage_cashier_accounts', 'Audit Cashier Accounts', 'Monitor cashier shift attendances and cash drawer reconciliations', 'Staff'),
  (22, 'process_refund', 'Process Refunds', 'Authorize return transactions, refunds and return restockings', 'Sales'),
  (23, 'manage_loyalty_customers', 'Manage CRM Customers', 'Lookup member profiles and register new loyalty members', 'Customers'),
  (24, 'adjust_loyalty_points', 'Adjust Loyalty Points', 'Manually edit customer tier ranks and reward points balances', 'Customers'),
  (25, 'delete_customers', 'Delete Customer Records', 'Permanently remove customer profiles from CRM records', 'Customers');
